   212	func pendingFullArchiveRefs(publications []checkpoint.PendingV2FullGenerationPublication) []plumbing.ReferenceName {
   213		seen := make(map[plumbing.ReferenceName]struct{}, len(publications))
   214		refs := make([]plumbing.ReferenceName, 0, len(publications))
   215		for _, publication := range publications {
   216			suffix, ok := strings.CutPrefix(publication.ArchiveRefName, paths.V2FullRefPrefix)
   217			if !ok || !checkpoint.GenerationRefPattern.MatchString(suffix) {
   218				continue
   219			}
   220			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + suffix)
   221			if _, ok := seen[refName]; ok {
   222				continue
   223			}
   224			seen[refName] = struct{}{}
   225			refs = append(refs, refName)
   226		}
   227		return refs
   228	}
